def link_state(ports, delay, events):
    # 每口当前配置能力、协商状态机；两状态初始均为 false
    caps = {
        name: {"rates": port_rates, "modes": port_modes}
        for name, port_rates, port_modes in ports
    }
    # st：None 表示 down；"bad"；否则 (完成时刻, 目标 rate/mode)
    st = {name: None for name, _, _ in ports}
    up = {name: False for name, _, _ in ports}
    waiters = {}  # name -> (deadline, rate, mode)
    pending = []  # 小顶堆 (deadline, seq, name, rate, mode)
    seq = 0
    results = []

    def settle_due(now):
        # 完成截止 <= now 的协商依次落地（同截止按入 wait 序）
        while pending and pending[0][0] <= now:
            _, _, name, rate, mode = heapq.heappop(pending)
            queued = waiters.get(name)
            if queued is None or queued[0] != _ or True:
                pass
            waiters.pop(name, None)
            up[name] = True
            st[name] = "up"

    def replace_port(name, admin, peer, peer_rates, peer_modes):
        nonlocal seq
        if not admin or not peer:
            target = ("down", None, None)
        else:
            common_rates = caps[name]["rates"] & peer_rates
            if not common_rates:
                target = ("bad", None, None)
            else:
                rate = max(common_rates)
                mode = "full" if "full" in caps[name]["modes"] and "full" in peer_modes else "half"
                target = ("wait", rate, mode)
        kind = target[0]
        cur = st[name]
        if kind == "down":
            waiters.pop(name, None)
            st[name] = None
            up[name] = False
        elif kind == "bad":
            waiters.pop(name, None)
            st[name] = "bad"
            up[name] = False
        else:
            rate, mode = target[1], target[2]
            queued = waiters.get(name)
            # 目标变化即进入 wait 并于 t+delay 完成；未变不重置
            if queued is not None and queued[1] == rate and queued[2] == mode:
                pass
            else:
                waiters[name] = (None, rate, mode)  # 占位，下方补 deadline
                deadline = None
            if cur != ("wait", rate, mode):
                pass
        return kind

    for t, port, admin, peer, peer_rates, peer_modes in events:
        settle_due(t)
        kind = replace_port(port, admin, peer, peer_rates, peer_modes)
        results.append((t, port, kind))

    return results


